def test_junit_uses_testcase_children_not_aggregate_counts(tmp_path):
    rows = gate.verify_junit(_junit(tmp_path / "unit.xml"), gate.REQUIRED_NODES)
    assert len(rows) == 7 and all(row["outcome"] == "PASS" for row in rows)


